"""BlastRadius against specs generated by a real FastAPI app (OpenAPI 3.1, Pydantic models)."""

import textwrap

import pytest
from typer.testing import CliRunner

from blastradius.cli import app as cli
from blastradius.diff import diff_specs
from blastradius.models import ChangeKind as K
from blastradius.models import Severity as S
from blastradius.spec import Spec

pytest.importorskip("fastapi")

APP_V1 = """
from typing import Literal, Optional

from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI(title="Users")


class Address(BaseModel):
    city: str


class User(BaseModel):
    id: int
    name: str
    nickname: Optional[str] = None
    address: Optional[Address] = None
    role: Literal["admin", "member"]


class NewUser(BaseModel):
    name: str


@app.get("/users/{user_id}", response_model=User)
def get_user(user_id: int): ...


@app.post("/users", response_model=User)
def create_user(body: NewUser): ...


@app.get("/users/{user_id}/avatar")
def get_avatar(user_id: int): ...
"""

# v2: nickname becomes an int, address.city is removed, a "guest" role is added,
# creating a user requires an email, and the avatar endpoint is gone.
APP_V2 = (
    APP_V1.replace("nickname: Optional[str]", "nickname: Optional[int]")
    .replace("class Address(BaseModel):\n    city: str", "class Address(BaseModel):\n    zip: str")
    .replace('Literal["admin", "member"]', 'Literal["admin", "member", "guest"]')
    .replace(
        "class NewUser(BaseModel):\n    name: str",
        "class NewUser(BaseModel):\n    name: str\n    email: str",
    )
    .replace('@app.get("/users/{user_id}/avatar")\ndef get_avatar(user_id: int): ...\n', "")
)


@pytest.fixture
def apps(tmp_path, monkeypatch):
    (tmp_path / "users_v1.py").write_text(textwrap.dedent(APP_V1))
    (tmp_path / "users_v2.py").write_text(textwrap.dedent(APP_V2))
    monkeypatch.chdir(tmp_path)
    monkeypatch.syspath_prepend(str(tmp_path))
    import users_v1
    import users_v2

    return users_v1.app, users_v2.app


def test_fastapi_changes_are_classified(apps):
    v1, v2 = apps

    changes = diff_specs(Spec(v1.openapi()), Spec(v2.openapi()))
    found = {(c.endpoint, c.kind, c.field): c.severity for c in changes}

    assert found[("GET /users/{user_id}/avatar", K.ENDPOINT_REMOVED, None)] is S.BREAKING
    assert found[("POST /users", K.REQUEST_FIELD_ADDED_REQUIRED, "email")] is S.BREAKING
    # Optional[str] -> Optional[int]: FastAPI writes these as anyOf [X, null].
    assert found[("GET /users/{user_id}", K.RESPONSE_FIELD_TYPE_CHANGED, "nickname")] is S.BREAKING
    # A field inside an Optional[Model] is still compared.
    assert found[("GET /users/{user_id}", K.RESPONSE_FIELD_REMOVED, "address.city")] is S.BREAKING
    assert found[("GET /users/{user_id}", K.RESPONSE_ENUM_VALUE_ADDED, "role")] is S.WARNING


def test_same_app_has_no_changes(apps):
    v1, _ = apps

    assert diff_specs(Spec(v1.openapi()), Spec(v1.openapi())) == []


def test_export_command(apps, tmp_path):
    result = CliRunner().invoke(cli, ["export", "users_v1:app", "-o", "spec.json"])

    assert result.exit_code == 0, result.output
    assert Spec.load(tmp_path / "spec.json").title == "Users"


@pytest.mark.parametrize(
    "target, message",
    [
        ("users_v1", "expected module:variable"),
        ("no_such_module:app", "could not import"),
        ("users_v1:missing", "no variable named"),
        ("users_v1:User", "no .openapi() method"),
    ],
)
def test_export_errors(apps, target, message):
    result = CliRunner().invoke(cli, ["export", target])

    assert result.exit_code == 2
    assert message in result.output
